pub fn on_data_column_sidecar(
    &mut self,
    data_column_sidecar: DataColumnSidecar<P>,
) -> Option<P2pMessage<P>> {
    let subnet_id =
        misc::compute_subnet_for_data_column_sidecar(self.config(), data_column_sidecar.index);

    self.controller().on_gossip_data_column_sidecar(
        Arc::new(data_column_sidecar),
        subnet_id,
        GossipId::default(),
        true,
    );

    self.controller().wait_for_tasks();
    self.next_p2p_message()
}

pub fn on_acceptable_block(&mut self, block: &Arc<SignedBeaconBlock<P>>) {
    assert!(matches!(self.on_block(block), Some(P2pMessage::Accept(_))));
}

pub fn on_ignorable_block(&mut self, block: &Arc<SignedBeaconBlock<P>>) {
    assert!(matches!(self.on_block(block), Some(P2pMessage::Ignore(_))));
}

pub fn on_valid_block(&mut self, block: &Arc<SignedBeaconBlock<P>>) {
    assert!(matches!(
        self.on_block(block),
        Some(P2pMessage::Accept(_) | P2pMessage::Ignore(_)),
    ));
}

pub fn on_invalid_block(&mut self, block: &Arc<SignedBeaconBlock<P>>) {
    assert!(matches!(
        self.on_block(block),
        Some(P2pMessage::Ignore(_) | P2pMessage::Reject(_, _)) | None,
    ));
}

pub fn on_block_with_missing_blobs(
    &mut self,
    block: &Arc<SignedBeaconBlock<P>>,
    blob_count: usize,
) {
    // If an optimistic beacon block is not accepted by the fork choice,
    // then it will not be propagated in gossipsub before it is fully validated (e.g. block arrives before blob).
    self.on_valid_block(block);

    let block_root = block.message().hash_tree_root();

    match self.next_execution_service_message() {
        Some(ExecutionServiceMessage::GetBlobs(params)) => match params {
            EngineGetBlobsParams::V1(EngineGetBlobsV1Params {
                block: block_with_missing_blobs,
                blob_identifiers,
                peer_id: _,
            }) => {
                let expected_identifiers = (0..blob_count)
                    .map(|index| BlobIdentifier {
                        block_root,
                        index: index.try_into().expect("usize should fit to u64"),
                    })
                    .collect::<Vec<_>>();
                assert_eq!(blob_identifiers, expected_identifiers);
                assert_eq!(block_with_missing_blobs, *block);
            }
            EngineGetBlobsParams::V2(EngineGetBlobsV2Params {
                block_or_sidecar,
                data_column_identifiers,
            }) => {
                assert!(data_column_identifiers
                    .iter()
                    .all(|id| id.block_root == block_root));
                assert!(!data_column_identifiers.is_empty());

                match block_or_sidecar {
                    BlockOrDataColumnSidecar::Block(block_with_missing_blobs) => {
                        assert_eq!(block_with_missing_blobs, *block)
                    }

pub fn on_gossip_data_column_sidecar(
    &self,
    data_column_sidecar: Arc<DataColumnSidecar<P>>,
    subnet_id: SubnetId,
    gossip_id: GossipId,
    block_seen: bool,
) {
    self.spawn_data_column_sidecar_task(
        data_column_sidecar,
        block_seen,
        DataColumnSidecarOrigin::Gossip(subnet_id, gossip_id),
    )
}

pub fn on_requested_blob_sidecar(
    &self,
    blob_sidecar: Arc<BlobSidecar<P>>,
    block_seen: bool,
    peer_id: PeerId,
) {
    self.spawn(BlobSidecarTask {
        store_snapshot: self.owned_store_snapshot(),
        mutator_tx: self.owned_mutator_tx(),
        wait_group: self.owned_wait_group(),
        blob_sidecar,
        state: None,
        block_seen,
        origin: BlobSidecarOrigin::Requested(peer_id),
        submission_time: Instant::now(),
        metrics: self.metrics.clone(),
    })
}

pub fn on_requested_data_column_sidecar(
    &self,
    data_column_sidecar: Arc<DataColumnSidecar<P>>,
    block_seen: bool,
    peer_id: PeerId,
) {
    let block_header = data_column_sidecar.signed_block_header.message;
    if !self.store_snapshot().is_forward_synced()
        && self
            .store_snapshot()
            .accepted_data_column_sidecar(block_header, data_column_sidecar.index)
    {
        debug!(
            "received data column sidecar has been accepted, ignore this one from peer {peer_id} \
             (index: {}, slot: {})",
            data_column_sidecar.index,
            data_column_sidecar.slot(),
        );
        return;
    }

    self.spawn(DataColumnSidecarTask {
        store_snapshot: self.owned_store_snapshot(),
        mutator_tx: self.owned_mutator_tx(),
        wait_group: self.owned_wait_group(),
        data_column_sidecar,
        state: None,
        block_seen,
        origin: DataColumnSidecarOrigin::Requested(peer_id),
        submission_time: Instant::now(),
        metrics: self.metrics.clone(),
    })
}

pub fn on_reconstruction(
    &self,
